from h import *
r=[]
r.append(R(7649613,"रिच फ्रूट केक",
"चाय के कप के साथ बिल्कुल सही, यह रिच फ्रूट केक स्वाद से भरपूर है और दोपहर के नाश्ते के लिए आदर्श है।",
"12","92 ग्राम",
["75 ग्राम किशमिश (सुल्ताना)","100 ग्राम मुनक्का (रेज़िन)","25 ग्राम कैंडिड पील (मुरब्बे में पका छिलका)","100 मिली उबलता पानी","1 मध्यम केला, मसला हुआ","2 अंडे, फेंटे हुए","75 मिली रेपसीड तेल","1 मध्यम तोरई, कद्दूकस की हुई (200 ग्राम)","1 सेब, कद्दूकस किया हुआ","1 गाजर, बारीक कद्दूकस की हुई","150 ग्राम साबुत गेहूँ का आटा","1 छोटा चम्मच बेकिंग पाउडर","3 छोटे चम्मच मिक्स्ड स्पाइस","6 ग्लेसे चेरी, आधी कटी हुई","20 ग्राम साबुत, छिले हुए बादाम"],
["ओवन को 170°C/गैस 3 पर पहले से गरम करें। एक कटोरे में किशमिश, मुनक्का और कैंडिड पील डालें, उबलते पानी से ढकें और अलग रख दें।","एक बड़े कटोरे में मसला हुआ केला, अंडे और तेल मिलाएँ और अच्छी तरह फेंटें।","तोरई, सेब और गाजर मिलाएँ, फिर आटा, बेकिंग पाउडर और मिक्स्ड स्पाइस मिला दें। इसके बाद सूखे फल, साथ में भिगोने का पानी भी, डालें।","अच्छी तरह मिलाएँ और बेकिंग पार्चमेंट से लाइन किए हुए 20 सेमी के केक टिन में डालें, ऊपर से चेरी और बादाम रखें। फ़ॉइल से ढकें और ओवन में 1½ घंटे तक बेक करें। पकाने का समय पूरा होने से 15–20 मिनट पहले फ़ॉइल हटा दें, फिर बचे हुए समय तक बेक करें।","सींक या चाकू से जाँचें, जो पकने पर साफ़ बाहर आनी चाहिए, और ओवन से निकाल लें।"],
["आप यह केक ग्लूटेन-मुक्त आटे से आसानी से बना सकते हैं, लेकिन आपके चुने हुए आटे के प्रकार के आधार पर आपको अतिरिक्त 50 मिली तरल डालना पड़ सकता है।","कोई भी सूखे फल अच्छे लगते हैं – आलूबुखारा, खुबानी, करेंट या मिले-जुले फल।","पकने के बाद, यदि आप चाहें, तो इस पर 1 छोटा चम्मच बहता हुआ शहद डाल सकते हैं।"]))
r.append(R(7651076,"जॉलॉफ़ राइस और चिकन",
"पश्चिमी अफ़्रीका का एक लोकप्रिय व्यंजन जो एक ही बर्तन में पकता है, इसलिए सप्ताह के बीच के सरल, स्वादिष्ट डिनर के लिए आदर्श है।",
"4","393 ग्राम",
["2 छोटे चम्मच रेपसीड तेल","1 बड़ा प्याज़ (170 ग्राम), कटा हुआ","350 ग्राम बिना त्वचा और बिना हड्डी की चिकन ब्रेस्ट, टुकड़ों में कटी हुई","1 बड़ी लाल शिमला मिर्च (170 ग्राम), कटी हुई","1 बड़ी पीली शिमला मिर्च (170 ग्राम), कटी हुई","2 फांक लहसुन, कुचला हुआ","3 सेमी ताज़ा अदरक की जड़, बारीक कटी हुई","आधी -1 स्कॉच बॉनेट मिर्च, कटी हुई","2 बड़े चम्मच टमाटर प्यूरी","200 ग्राम ब्राउन बासमती चावल, ठंडे पानी से धोया हुआ।","1 कम नमक वाला चिकन स्टॉक क्यूब, 450 मिली पानी में घुला हुआ","1 x 400 ग्राम का डिब्बा कटे हुए टमाटर","100 ग्राम भिंडी, 2 सेमी के टुकड़ों में कटी हुई","2 बड़े चम्मच मोटा कटा हुआ धनिया"],
["एक बड़े पैन में तेल गरम करें, फिर प्याज़ डालें और 3-4 मिनट तक पकाएँ, जब तक वह भूरा होना शुरू न हो जाए।","चिकन के टुकड़े डालें और 3-4 मिनट और पकाएँ, बीच-बीच में चलाते रहें ताकि चिकन बराबर पके।","लाल और पीली शिमला मिर्च डालकर 2 मिनट और चलाएँ, फिर लहसुन, अदरक, मिर्च और टमाटर प्यूरी डालकर अच्छी तरह मिलाएँ।","अब चावल डालें और फिर से मिलाएँ, एक मिनट तक चलाएँ ताकि सारे चावल पर टमाटर प्यूरी का मिश्रण लग जाए।","स्टॉक और टमाटर डालकर अच्छी तरह मिलाएँ, उबाल आने दें, फिर आँच कम करें, ढक दें और 8 मिनट तक धीमी आँच पर पकाएँ।","भिंडी को चावल के ऊपर बिखेर दें, ढक्कन वापस लगाएँ और 5 मिनट और धीमी आँच पर पकाएँ।","अब आँच बंद कर दें, लेकिन ढक्कन न हटाएँ और 5 मिनट तक ऐसे ही रहने दें। धनिया डालें, अच्छी तरह मिलाएँ और परोसें।"],
["आप यह व्यंजन भेड़ के मांस, बीफ़, सूअर के मांस या टर्की के साथ भी बना सकते हैं।","शाकाहारी/वीगन संस्करण के लिए चिकन की जगह तोरई, बैंगन के टुकड़े और मैरिनेट किया हुआ टोफू डालें और वेजिटेबल स्टॉक क्यूब का उपयोग करें।","सीफ़ूड संस्करण के लिए फ़िश स्टॉक क्यूब का उपयोग करें और भिंडी के साथ सैल्मन के टुकड़े या कुछ झींगे डालें।",FZ+"जल्दी ठंडा करें। फ्रिज में पिघलाएँ और पूरी तरह गरम होने तक, यानी भाप निकलने तक, दोबारा गरम करें। तुरंत खाएँ और बचा हुआ फेंक दें।",FV(3)]))
r.append(R(7652430,"सेब, ब्लैकबेरी, ओट्स और बीजों का क्रम्बल",
"यह कम वसा वाला क्रम्बल बनाने में झटपट और आसान है।",
"4","152 ग्राम",
["100 ग्राम ताज़ा साबुत गेहूँ की ब्रेड का चूरा","50 ग्राम रोल्ड ओट्स","1 बड़ा चम्मच कद्दू के बीज","2 खाने वाले सेब","150 ग्राम ब्लैकबेरी","50 मिली सेब का रस","1 बड़ा चम्मच बहता हुआ शहद","परोसने के लिए हाफ़-फ़ैट क्रीम फ्रेश या सादा दही"],
["ओवन को 180°C/गैस मार्क 4 पर पहले से गरम करें। ब्रेड का चूरा, ओट्स और कद्दू के बीज एक कटोरे में डालें और अच्छी तरह मिलाएँ।","सेबों का बीज निकालकर छिलके सहित काट लें और ओवन-सुरक्षित डिश में रखें। ब्लैकबेरी डालें, फिर डिश में सेब का रस डालें।","क्रम्बल का मिश्रण फलों के ऊपर बिखेर दें, फिर ऊपर से शहद डालें।","ओवन में लगभग 15–20 मिनट तक सुनहरा भूरा होने तक बेक करें।","क्रम्बल को तुरंत परोसें, साथ में एक चम्मच हाफ़-फ़ैट क्रीम फ्रेश या सादा दही डालें।"],
["इस रेसिपी में पकाने वाले सेबों की जगह खाने वाले सेब इस्तेमाल करने से आपको अतिरिक्त चीनी डालने की ज़रूरत नहीं पड़ती। ऐसा इसलिए है क्योंकि खाने वाले सेब स्वाभाविक रूप से ज़्यादा मीठे होते हैं।","सेब के छिलकों में फ़ाइबर होता है, इसलिए उन्हें छीलने से बचें।","ब्लैकबेरी विटामिन C सहित एंटीऑक्सिडेंट से भरपूर होती हैं, और वे फ़ाइबर का भी अच्छा स्रोत हैं।","ओट्स जैसे साबुत अनाज में बीटा-ग्लूकन नामक एक प्रकार का फ़ाइबर होता है, जो नियमित रूप से खाने पर कोलेस्ट्रॉल कम करने में मदद कर सकता है।"]))
r.append(R(7654528,"वियतनामी कुरकुरा मूँगफली सलाद",
"सब्ज़ियों से भरा नूडल सलाद – चलते-फिरते लंच के लिए बढ़िया।",
"2","294 ग्राम",
["150 ग्राम सूखे एग नूडल्स","2 छोटे चम्मच भुना हुआ तिल का तेल","1 छोटा चम्मच रेपसीड तेल","1 लाल शिमला मिर्च, माचिस की तीलियों जैसे पतले टुकड़ों में कटी हुई","4 सेमी ताज़ा अदरक की जड़, बारीक कटी हुई","चौथाई छोटी लाल मिर्च, बारीक कटी हुई (वैकल्पिक)","4 हरे प्याज़, छंटे हुए और कटे हुए","150 ग्राम अंकुरित मूँग (बीन स्प्राउट्स)","मुट्ठी भर ताज़ा कटी हुई धनिया की पत्तियाँ","5 सेमी खीरा, छोटे टुकड़ों में कटा हुआ","आधे नींबू (लाइम) का रस","30 ग्राम प्राकृतिक, बिना नमक वाली मूँगफली, मोटी कटी हुई","यदि चाहें तो 2 छोटे चम्मच कम नमक वाला सोया सॉस"],
["नूडल्स को पैकेट के निर्देशों के अनुसार पकाएँ (समय अलग-अलग होता है – आमतौर पर 4–6 मिनट), पानी निथारें और उन्हें तुरंत ठंडे पानी में डाल दें ताकि वे और न पकें। फिर से पानी निथारें और एक कटोरे में भुने हुए तिल के तेल के साथ मिलाएँ, अच्छी तरह मिलाकर अलग रख दें।","इस बीच, एक पैन में रेपसीड तेल डालें, फिर लाल शिमला मिर्च, अदरक और मिर्च (यदि इस्तेमाल कर रहे हों) डालें और 2 मिनट तक चलाएँ।","इसके बाद, हरे प्याज़ और अंकुरित मूँग डालें, 1 मिनट तक उछालते हुए चलाएँ और फिर आँच से उतार लें।","अंकुरित मूँग के मिश्रण को नूडल्स में डालें, साथ में धनिया, खीरा, नींबू (लाइम) का रस और आधी मूँगफली मिलाएँ, और अच्छी तरह मिलाएँ।","इसे लंच बॉक्स में डालें और ऊपर से बाक़ी मूँगफली बुरक दें, यदि चाहें तो स्वाद के लिए हर एक में 1 छोटा चम्मच सोया सॉस डालें।"],
["इस रेसिपी में नमक की मात्रा कम करने के लिए कम नमक वाला सोया सॉस चुनें। वैकल्पिक रूप से, रेसिपी को और सेहतमंद बनाने के लिए इस सामग्री को पूरी तरह छोड़ दें।","ग्लूटेन-मुक्त सलाद के लिए चावल के नूडल्स का उपयोग करें और यदि सोया सॉस इस्तेमाल कर रहे हैं, तो उसकी जगह ग्लूटेन-मुक्त तामारी लें।","आप इस रेसिपी को अखरोट, सूरजमुखी के बीज और कद्दू के बीजों के मिश्रण के साथ भी आज़मा सकते हैं।",FV(2)]))
r.append(R(7658821,"फूलगोभी और लीक का सूप",
"एक पेट भरने वाला गरम सूप जो बनाने में झटपट और सस्ता है। मसालेदार, भुने हुए फूलगोभी के क्रूटन के साथ यह एक स्वादिष्ट भोजन है।",
"6","283 ग्राम",
["2 छोटे चम्मच रेपसीड तेल + बेकिंग शीट पर लगाने के लिए 1 छोटा चम्मच","1 फूलगोभी (800 ग्राम), फूलों में कटी हुई","1 ढेर वाला छोटा चम्मच हल्दी","1 बड़ा प्याज़, कटा हुआ","2 लीक, कटे हुए","1 छोटा चम्मच पिसा जीरा","2 फांक लहसुन, कुचला हुआ","एक अच्छी चुटकी सफ़ेद मिर्च","1 कम नमक वाला वेजिटेबल स्टॉक क्यूब, 600 मिली पानी में","1 x 400 ग्राम का डिब्बा बटर बीन्स, पानी निथारा हुआ (240 ग्राम)","300 मिली स्किम्ड दूध","स्वादानुसार काली मिर्च"],
["ओवन को 180°C/गैस मार्क 4 पर पहले से गरम करें और एक बेकिंग शीट पर हल्का तेल लगाएँ।","फूलगोभी के ¼ हिस्से को बहुत छोटे फूलों में तोड़ें, ठंडे पानी से धोएँ, ज़्यादा पानी झाड़ दें और एक कटोरे में डालें। ऊपर से हल्दी छिड़कें और अच्छी तरह मिलाएँ। बेकिंग शीट पर रखें और किनारे जलने शुरू होने तक 10-15 मिनट तक रोस्ट करें, फिर अलग रख दें।","इस बीच, एक पैन में 2 छोटे चम्मच तेल डालें और प्याज़ डालें। 3-4 मिनट तक नरम होने तक पकाएँ, लेकिन भूरा न होने दें। लीक और बची हुई फूलगोभी डालें और बीच-बीच में चलाते हुए 3-4 मिनट और पकाएँ।","जीरा, लहसुन, मिर्च और स्टॉक डालकर उबाल आने दें। आँच कम करें, ढक दें और फूलगोभी के पकने तक 8-10 मिनट धीमी आँच पर पकाएँ।","बटर बीन्स डालें और धीरे-धीरे दूध मिलाते हुए चिकना होने तक ब्लेंड करें। गरम होने तक लाएँ, फिर 6 कटोरों में बाँट दें और ऊपर से भुनी हुई फूलगोभी और भरपूर ताज़ी पिसी काली मिर्च डालें।"],
["इस सूप के लिए आप फ़्लाजियोलेट जैसी अन्य बीन्स भी आज़मा सकते हैं।","लहसुन और जीरे के साथ सूप में 1-2 छोटे चम्मच करी पेस्ट या पाउडर डालकर देखें।","आप सूप पहले से बनाकर दोबारा गरम कर सकते हैं - परोसने से ठीक पहले तक व्यंजन के ऊपर फूलगोभी के क्रूटन न डालें।",FZ+"फूलगोभी के क्रूटन अलग से फ्रीज़ करें। माइक्रोवेव में या बहुत धीमी आँच पर भाप निकलने तक पिघलाकर गरम करें।",FV(3)]))
r.append(R(7659110,"2 सामग्री वाले पैनकेक",
"इस बेहद तेज़ नाश्ते के लिए आपको केवल दो मुख्य सामग्रियों की ज़रूरत है।",
"1","427 ग्राम",
["2 केले, मसले हुए","1 अंडा, हल्का फेंटा हुआ","कैलोरी-नियंत्रित कुकिंग स्प्रे",["टॉपिंग","परोसने के लिए 2 बड़े चम्मच 0% फ़ैट वाला सादा ग्रीक योगर्ट और ताज़ी बेरीज़"],["टॉपिंग","1 छोटा चम्मच एगेव सिरप (वैकल्पिक)"]],
["केले और अंडे को एक चुटकी नमक के साथ मिलाएँ।","फ्राइंग पैन पर कुकिंग स्प्रे छिड़कें और गरम करें। एक कलछी मिश्रण पैन में डालें और हर तरफ़ 2 मिनट तक सुनहरा होने तक पकाएँ। इसे दोहराएँ।","हर पैनकेक को योगर्ट, ताज़ी बेरीज़ और एगेव सिरप के साथ परोसें।"],
["आप टॉपिंग के रूप में अपने पसंदीदा किसी भी फल को आज़मा सकते हैं, या यहाँ तक कि अपना पसंदीदा नट बटर भी।"]))
r.append(R(7659367,"घर पर बने सब्ज़ियों के चिप्स",
"बिना अतिरिक्त नमक वाले इन कम वसा वाले घर पर बने सब्ज़ियों के चिप्स के साथ अपने पसंदीदा स्वादों का मेल तैयार करें।",
"6","74 ग्राम",
["120 ग्राम शकरकंद","120 ग्राम गाजर","100 ग्राम पार्सनिप","100 ग्राम चुकंदर","15 छिड़काव स्प्रे तेल"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। सब्ज़ियों को बहुत पतला काटें – मैंडोलिन स्लाइसर एकदम सही रहता है।","बेकिंग शीट पर थोड़ा तेल स्प्रे करें और सब्ज़ियों के स्लाइस इस तरह बिछाएँ कि वे एक-दूसरे पर न चढ़ें। आपके ओवन के आकार के आधार पर आपको इन्हें अलग-अलग खेपों में बनाना पड़ सकता है।","20 मिनट तक हल्का भूरा होने तक पकाएँ। पकाते समय सब्ज़ियों को बार-बार पलटना बेहद ज़रूरी है क्योंकि वे आसानी से जल सकती हैं। 20 मिनट पूरे होने से पहले आपको कुछ चिप्स निकालने पड़ सकते हैं, क्योंकि कुछ दूसरों से जल्दी पक जाएँगे।","जब सारे चिप्स तैयार हो जाएँ, तो ठंडा होने दें, फिर मिलाकर परोसें।"],
["ध्यान रखें कि आपकी सब्ज़ियाँ जलें नहीं। जड़ वाली सब्ज़ियों में बहुत प्राकृतिक चीनी होती है, इसलिए यदि ओवन बहुत तेज़ है या आप पकाते समय पर्याप्त बार नहीं पलटते, तो वे झुलस सकती हैं।","आप चिप्स को माइक्रोवेव में 300W पर 10 मिनट तक, फिर पूरी पावर पर 1 मिनट तक पका सकते हैं, जो काफ़ी अच्छा काम करता है लेकिन केवल छोटी खेपों के लिए।","इन्हें एयर फ्रायर में भी कुरकुरा होने तक पकाया जा सकता है।"]))
r.append(R(7660536,"मसालेदार पोच किए हुए नाशपाती",
"कम कैलोरी वाली मिठाई जो मेहमानों के लिए परोसने जितनी ख़ास है।",
"4","200 ग्राम",
["200 मिली अंगूर का रस","1 दालचीनी की छड़ी","3 इलायची की फलियाँ","1 छोटा चम्मच वनीला एसेंस","4 पके नाशपाती, छिले हुए, बीज निकाले हुए और आधे कटे हुए"],
["अंगूर का रस, दालचीनी की छड़ी, इलायची की फलियाँ और वनीला एसेंस को 300 मिली पानी के साथ एक बड़े पैन में डालें।","धीरे-धीरे गरम करें, ध्यान रखें कि उबाल न आए। इसमें केवल कुछ मिनट लगेंगे। नाशपाती डालें। ढक दें और 10–12 मिनट तक या नाशपाती के थोड़े नरम होने तक धीमी आँच पर पकाएँ।","नाशपाती को गरम-गरम, थोड़े पकाने वाले तरल के साथ परोसें।"],
["वसा और कैलोरी कम करने के लिए 0% फ़ैट वाले ग्रीक योगर्ट के साथ परोसें।",FV(1)]))
